"""
Generate src/shamunits/doc/godbolt.cpp, a single-file version of shamunits
plus the example main from src/shamunits/exemple.cpp, for Compiler Explorer.

Usage: python tools/gen_shamunits_amalgamation.py [--check]
  --check : do not write, exit non-zero with a diff if the file is stale
"""

import argparse
import difflib
import re
import sys
from pathlib import Path

root = Path(__file__).resolve().parent.parent
shamunits_dir = root / "src" / "shamunits"
include_dir = shamunits_dir / "include" / "shamunits"
roots = [
    include_dir / name
    for name in [
        "Constants.hpp",
        "UnitSystem.hpp",
        "unit_table.hpp",
        "prefix_table.hpp",
        "constant_table.hpp",
    ]
]
example = shamunits_dir / "exemple.cpp"
output = shamunits_dir / "doc" / "godbolt.cpp"

local_include = re.compile(r'^\s*#\s*include\s*"([^"]+)"')
system_include = re.compile(r"^\s*#\s*include\s*<([^>]+)>")
pragma_once = re.compile(r"^\s*#\s*pragma\s+once\b")
banner = "/" * 68


def split_license(path):
    """Return (license block, remaining lines) of a file starting with the license header."""
    lines = path.read_text().splitlines()
    rule = lines[0]
    end = lines.index(rule, 1) + 1
    return lines[:end], lines[end:]


def resolve_local(path, inc):
    """Resolve `#include "inc"` seen in `path`: relative to it, else as "shamunits/..."."""
    candidate = path.parent / inc
    if not candidate.exists():
        candidate = include_dir.parent / inc
    return candidate.resolve()


def inline(path, seen, sys_includes, out):
    if path in seen:
        return
    seen.add(path)
    out += ["", f"// begin {path.relative_to(include_dir.parent)}"]
    body = [line for line in split_license(path)[1] if not pragma_once.match(line)]
    while body and not body[0].strip():
        body.pop(0)
    for line in body:
        if m := local_include.match(line):
            inline(resolve_local(path, m.group(1)), seen, sys_includes, out)
        elif m := system_include.match(line):
            sys_includes.setdefault(m.group(1), None)
        else:
            out.append(line)
    out.append(f"// end {path.relative_to(include_dir.parent)}")


def generate():
    license_block, example_body = split_license(example)
    seen, sys_includes, lib = set(), {}, []
    for path in roots:
        inline(path.resolve(), seen, sys_includes, lib)

    # Drop the example's includes of shamunits itself, keep everything else as is.
    is_shamunits_include = re.compile(r'^\s*#\s*include\s*[<"](shamunits/)?[^>"]*\.hpp[>"]')
    example_body = [line for line in example_body if not is_shamunits_include.match(line)]

    out = license_block + [
        "",
        "// This file is generated by tools/gen_shamunits_amalgamation.py, do not edit it.",
        "// Edit the shamunits headers or src/shamunits/exemple.cpp and re-run the script.",
        "",
        "// clang-format off",
        "",
        *(banner, banner, banner),
        "// shamrock units lib",
        "// Go to the bottom of the file to try",
        *(banner, banner, banner),
        "",
        *(f"#include <{inc}>" for inc in sys_includes),
        *lib,
        "",
        *(banner, banner, banner),
        "// user source starts here",
        *(banner, banner, banner),
        *example_body,
    ]
    return "\n".join(out) + "\n"


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="fail if the output is stale")
    args = parser.parse_args()

    new = generate()
    rel = output.relative_to(root)
    if not args.check:
        output.write_text(new)
        print(f"wrote {rel}")
        return 0

    old = output.read_text() if output.exists() else ""
    if old == new:
        print(f"{rel} is up to date")
        return 0
    sys.stdout.writelines(
        difflib.unified_diff(
            old.splitlines(keepends=True), new.splitlines(keepends=True), str(rel), str(rel)
        )
    )
    print(f"\n{rel} is stale, run: python tools/gen_shamunits_amalgamation.py")
    return 1


if __name__ == "__main__":
    sys.exit(main())
